    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    import math
    for i in range(2, int(math.isqrt(n)) + 1):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n:step] = b'\x00' * ((n - 1 - start) // step + 1)
    return sum(sieve)

