    if isinstance(lst, (list, tuple)):
        stack = [iter([lst])]
        # Actually simpler stack of lists
        stack = [lst[::-1] if isinstance(lst, list) else list(reversed(list(lst)))]
        # We'll use list as stack of items
        # Re-init properly:
        stack = list(reversed(lst)) if isinstance(lst, list) else list(reversed(list(lst)))
        # wait reversed(list) needs sequence; for generality:
        # redo cleanly below
        stack = []
        # push in reverse
        try:
            seq = list(lst)
        except Exception:
            return [lst]
        for v in reversed(seq):
            stack.append(v)
        while stack:
            x = stack.pop()
            if isinstance(x, (list, tuple)):
                for v in reversed(list(x)):
                    stack.append(v)
            else:
                out.append(x)
        return out
    else:
        return [lst]

