        try:
            s = str(s)
        except:
            return False
        # if original wasn't str, treat as invalid unless it converts?
        # Safer: only accept str
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set('([{')
    for ch in s:
        if ch in opens:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return len(stack) == 0

