def solve(s):
    if s is None:
        return 0
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except:
            s = str(s)
    if not isinstance(s, str):
        # if list of chars etc, join if possible
        try:
            # if it's a list/tuple, treat as sequence
            if isinstance(s, (list, tuple)):
                s = ''.join(map(str, s))
            else:
                return 0
        except:
            return 0
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        cur = i - start + 1
        if cur > best:
            best = cur
    return best

